func TestB10FileSessionWarnsWithoutClose(t *testing.T) {
	warned := newWarnings()
	log.SetOutput(warned)
	defer log.SetOutput(os.Stderr)
	gone := func() weak.Pointer[FileSession] {
		made0, failure1 := FileSessionsInDirectory(casePath(t, "."), ptr(uint64(1440)))
		if failure1 != nil {
			t.Fatalf("GN-13f: %v", failure1)
		}
		made2, failure3 := made0.Open(nil)
		if failure3 != nil {
			t.Fatalf("GN-13f: %v", failure3)
		}
		return weak.Make(made2)
	}()
	runtime.GC()
	if gone.Value() != nil {
		t.Fatalf("B-10: the collection left the object, so its cleanup does not run")
	}
	warned.await("FileSession was destroyed without Close(), so its destructor released it (B-10)")
}

